select country, case when country in ('SG', 'US') then 'tier_1' else 'other' end as country_group, sum(rating) as total_rating, sort_array(collect_set(country)) as country_list, count(distinct rating) as unique_countrys from suppliers where rating between 2.8 and 3.6 group by 1, 2 having count(distinct rating) > 2 order by unique_countrys asc, country asc, country_group asc limit 3
